INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM204QECF', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'What is the sum of the solutions to the equation $x^2 - 13x + 40 = 0$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '13', ARRAY['13'], E'Factoring gives $(x - 5)(x - 8) = 0$, so the solutions are $x = 5$ and $x = 8$. The sum is $5 + 8 = 13$. Alternatively, by Vieta''s formulas, the sum of the solutions of $x^2 + bx + c = 0$ equals $-b$. Here $-(-13) = 13$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20IM6GB', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'grid_in', E'The function $h$ is defined by $h(x) = 2(3)^x$. If $h(a) = 162$, what is the value of $h(a - 2)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '18', ARRAY['18'], E'From $h(a) = 2(3)^a = 162$, dividing both sides by $2$ gives $3^a = 81 = 3^4$, so $a = 4$. Then $h(a - 2) = h(2) = 2(3)^2 = 2(9) = 18$. Alternatively, $h(a - 2) = 2(3)^{a-2} = 2 \\cdot \\frac{3^a}{3^2} = \\frac{2 \\cdot 81}{9} = 18$. A common error is computing $h(a) - 2 = 162 - 2 = 160$ by misreading $h(a-2)$ as $h(a) - 2$. Another error is dividing $162$ by $2$ to get $81$ and stopping there without evaluating $h(a - 2)$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20RDIFH', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'Which of the following equations represents the line that passes through the points $(3, 11)$ and $(7, 31)$?', NULL, $lyceon_json$[{"key":"A","text":"$y = 4x - 1$"},{"key":"B","text":"$y = 5x - 15$"},{"key":"C","text":"$y = 5x - 4$"},{"key":"D","text":"$y = 5x + 4$"}]$lyceon_json$::jsonb, 'C', NULL, E'The slope is $\\frac{31 - 11}{7 - 3} = \\frac{20}{4} = 5$. Using point-slope form with $(3, 11)$: $y - 11 = 5(x - 3)$, which gives $y = 5x - 15 + 11 = 5x - 4$. The equation $y = 4x - 1$ results from miscalculating the denominator $7 - 3$ as $5$ instead of $4$, giving a slope of $\\frac{20}{5} = 4$. The equation $y = 5x - 15$ uses the correct slope but omits adding back the $y$-coordinate $11$ after applying point-slope form. The equation $y = 5x + 4$ has a sign error in the $y$-intercept computation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2128GUM', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'A circle has center $(-3, 4)$ and passes through the point $(5, 19)$. What is the equation of this circle?', NULL, $lyceon_json$[{"key":"A","text":"$(x + 3)^2 + (y - 4)^2 = 289$"},{"key":"B","text":"$(x - 3)^2 + (y + 4)^2 = 289$"},{"key":"C","text":"$(x + 3)^2 + (y - 4)^2 = 17$"},{"key":"D","text":"$(x + 3)^2 + (y + 4)^2 = 289$"}]$lyceon_json$::jsonb, 'A', NULL, E'The radius is the distance from $(-3, 4)$ to $(5, 19)$: $r = \\sqrt{(5-(-3))^2 + (19-4)^2} = \\sqrt{64 + 225} = \\sqrt{289} = 17$. The equation is $(x+3)^2 + (y-4)^2 = 289$. The answer $(x-3)^2 + (y+4)^2 = 289$ uses wrong signs for both center coordinates, writing subtraction instead of addition for $x$ and addition instead of subtraction for $y$. The answer $(x+3)^2 + (y-4)^2 = 17$ uses $r$ instead of $r^2$ on the right side. The answer $(x+3)^2 + (y+4)^2 = 289$ has an incorrect sign for the $y$-coordinate of the center, writing $(y+4)$ instead of $(y-4)$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21RWGF8', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A pharmaceutical company randomly assigns $300$ patients to receive either a new medication or a placebo. After $12$ weeks, patients taking the medication show a significantly greater reduction in blood pressure than those taking the placebo. Which of the following conclusions is best supported by this study design?', NULL, $lyceon_json$[{"key":"A","text":"The medication caused the reduction in blood pressure."},{"key":"B","text":"There is an association between the medication and blood pressure reduction, but causation cannot be established."},{"key":"C","text":"The results apply to all adults, regardless of health status."},{"key":"D","text":"Patients who chose the medication had better outcomes than those who chose the placebo."}]$lyceon_json$::jsonb, 'A', NULL, E'Because this is a randomized controlled experiment with random assignment to treatment and control groups, a causal conclusion is supported. The medication caused the reduction in blood pressure. Claiming that only an association can be established fails to recognize that random assignment controls for confounding variables, which is precisely what allows causal inference. Generalizing the results to all adults regardless of health status goes beyond the scope of the study — the results apply to the population from which the $300$ patients were drawn. Stating that patients chose their group misreads the study design; the stem specifies random assignment, not self-selection.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21YV6MK', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'Two parallel lines are cut by a transversal. One of the angles formed measures $131^\\circ$. A triangle is formed using part of the transversal and segments of the two parallel lines, where one of the triangle''s angles is supplementary to the $131^\\circ$ angle. If another angle of this triangle measures $37^\\circ$, what is the measure of the third angle of the triangle?', NULL, $lyceon_json$[{"key":"A","text":"$94^\\circ$"},{"key":"B","text":"$86^\\circ$"},{"key":"C","text":"$49^\\circ$"},{"key":"D","text":"$12^\\circ$"}]$lyceon_json$::jsonb, 'A', NULL, E'The angle supplementary to $131^\\circ$ is $180^\\circ - 131^\\circ = 49^\\circ$. The third angle of the triangle is $180^\\circ - 49^\\circ - 37^\\circ = 94^\\circ$. The answer $86^\\circ$ comes from an arithmetic error such as computing $180 - 49 - 37$ as $86$. The answer $49^\\circ$ results from stopping at the supplementary angle and not computing the third angle. The answer $12^\\circ$ comes from incorrectly subtracting $49 - 37 = 12$ instead of using the triangle angle sum.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22AZFUF', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'grid_in', E'A store increases the price of an item by $20\\%$. Later, the store applies a $20\\%$ discount to the new price. If the final price is $\\$57.60$, what was the original price of the item, in dollars?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '60', ARRAY['60'], E'Let the original price be $p$. After a $20\\%$ increase, the price becomes $1.20p$. After a $20\\%$ discount on the new price, the final price is $0.80 \\times 1.20p = 0.96p$. Setting $0.96p = 57.60$ gives $p = \\frac{57.60}{0.96} = 60$. A common error is assuming the $20\\%$ increase and $20\\%$ decrease cancel out, concluding $p = 57.60$. Another error is reversing the operations, dividing $57.60$ by $1.20$ first to get $48$, then dividing by $0.80$ to get $60$ — while reordering happens to yield the correct answer here, applying only the first step gives the incorrect intermediate value $48$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22G4QVX', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'grid_in', E'In a right triangle, the two legs have lengths $13$ and $84$. What is the length of the hypotenuse?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '85', ARRAY['85'], E'Using the Pythagorean theorem, the hypotenuse $c$ satisfies $c^2 = 13^2 + 84^2 = 169 + 7056 = 7225$. Taking the square root, $c = \\sqrt{7225} = 85$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM230S2O3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher collects data on the number of hours spent studying and the corresponding exam scores for $15$ students. The line of best fit is $y = 4.7x + 51$, where $x$ is hours studied and $y$ is the predicted exam score. A student who studied for $8$ hours scored $83$ on the exam. What is the residual for this student?', NULL, $lyceon_json$[{"key":"A","text":"$-5.6$"},{"key":"B","text":"$5.6$"},{"key":"C","text":"$-4.8$"},{"key":"D","text":"$83$"}]$lyceon_json$::jsonb, 'A', NULL, E'The predicted score for $x = 8$ is $y = 4.7(8) + 51 = 37.6 + 51 = 88.6$. The residual is actual minus predicted: $83 - 88.6 = -5.6$. The answer $5.6$ results from computing predicted minus actual instead of actual minus predicted, reversing the sign. The answer $-4.8$ arises from an arithmetic slip such as computing $4.7 \\times 8$ as $36.8$ instead of $37.6$, which gives a predicted value of $87.8$ and a residual of $83 - 87.8 = -4.8$. The answer $83$ simply restates the actual score without performing the residual calculation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM230WSU9', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'What is the value of $y$ in the solution to the system of equations below?$$\\begin{cases} 2x + y = 19 \\\\ x - y = 5 \\end{cases}$$', NULL, $lyceon_json$[{"key":"A","text":"$-3$"},{"key":"B","text":"$5$"},{"key":"C","text":"$3$"},{"key":"D","text":"$8$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $3$. Adding the two equations eliminates $y$: $(2x + y) + (x - y) = 19 + 5$, giving $3x = 24$, so $x = 8$. Substituting into $x - y = 5$ gives $8 - y = 5$, so $y = 3$. The distractor $-3$ results from a sign error when solving $8 - y = 5$, incorrectly obtaining $y = -3$. The distractor $5$ comes from returning the value of $x - y$ rather than $y$ itself. The distractor $8$ results from finding $x = 8$ and reporting it instead of the requested $y$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM251P6H3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A jacket originally priced at $\\$130$ is on sale for $35\\%$ off. What is the sale price of the jacket?', NULL, $lyceon_json$[{"key":"A","text":"$\\$45.50$"},{"key":"B","text":"$\\$84.50$"},{"key":"C","text":"$\\$95.00$"},{"key":"D","text":"$\\$175.50$"}]$lyceon_json$::jsonb, 'B', NULL, E'The discount is $0.35 \\times 130 = 45.50$. The sale price is $130 - 45.50 = 84.50$. The answer $\\$45.50$ is the discount amount itself, not the sale price, resulting from misreading what the question asks. The answer $\\$95.00$ comes from subtracting $35$ as a dollar amount instead of computing $35\\%$. The answer $\\$175.50$ results from adding the discount to the original price instead of subtracting.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25E10IV', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A cylindrical water tank has a radius of $5$ feet and a height of $14$ feet. What is the volume of the tank, in cubic feet?', NULL, $lyceon_json$[{"key":"A","text":"$350\\pi$"},{"key":"B","text":"$140\\pi$"},{"key":"C","text":"$700\\pi$"},{"key":"D","text":"$70\\pi$"}]$lyceon_json$::jsonb, 'A', NULL, E'The volume of a cylinder is $V = \\pi r^2 h = \\pi(5)^2(14) = 350\\pi$ cubic feet. The answer $140\\pi$ results from using $\\pi d h = \\pi(10)(14)$, confusing the diameter with the base area computation. The answer $700\\pi$ comes from using the diameter squared instead of the radius squared: $\\pi(10)^2(14)/2$ or a similar miscalculation doubling the result. The answer $70\\pi$ comes from computing $\\pi r h = \\pi(5)(14) = 70\\pi$, omitting the squaring of the radius.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25NAIRB', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A cone has a slant height of $85$ centimeters and a base radius of $36$ centimeters. What is the volume of the cone, in cubic centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$33264\\pi$"},{"key":"B","text":"$99792\\pi$"},{"key":"C","text":"$36720\\pi$"},{"key":"D","text":"$11088\\pi$"}]$lyceon_json$::jsonb, 'A', NULL, E'First find the height using the Pythagorean theorem with the slant height and radius: $h = \\sqrt{85^2 - 36^2} = \\sqrt{7225 - 1296} = \\sqrt{5929} = 77$ cm. The volume of a cone is $V = \\frac{1}{3}\\pi r^2 h = \\frac{1}{3}\\pi(36)^2(77) = \\frac{99792\\pi}{3} = 33264\\pi$ cubic centimeters. The answer $99792\\pi$ results from omitting the $\\frac{1}{3}$ factor, computing $\\pi r^2 h$ directly. The answer $36720\\pi$ comes from using the slant height $85$ instead of the actual height $77$ in the volume formula: $\\frac{1}{3}\\pi(36)^2(85) = \\frac{110160\\pi}{3} = 36720\\pi$. The answer $11088\\pi$ results from applying the $\\frac{1}{3}$ factor a second time to the already-correct result.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25TZV13', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'grid_in', E'What is the value of $x$ that satisfies the equation $$\\frac{2x + 3}{5} - \\frac{x - 7}{3} = 1\\,?$$', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-29', ARRAY['-29'], E'Multiplying every term by the least common denominator $15$ gives $3(2x + 3) - 5(x - 7) = 15$. Expanding: $6x + 9 - 5x + 35 = 15$, which simplifies to $x + 44 = 15$. Subtracting $44$ from both sides yields $x = -29$. A common error is distributing the negative sign incorrectly in $-5(x - 7)$, writing $-5x - 35$ instead of $-5x + 35$, which leads to $x - 26 = 15$ and $x = 41$. Another error is forgetting to multiply the right side by the LCD, leaving $x + 44 = 1$ and obtaining $x = -43$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26JTOVX', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'A linear function $g$ satisfies $g(2) = 3$ and $g(5) = 12$. The function $h$ is defined by $h(x) = g(x) + 7$. What is the $y$-intercept of the graph of $y = h(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$-3$"},{"key":"B","text":"$4$"},{"key":"C","text":"$7$"},{"key":"D","text":"$10$"}]$lyceon_json$::jsonb, 'B', NULL, E'The slope of $g$ is $\\frac{12 - 3}{5 - 2} = \\frac{9}{3} = 3$. Using point-slope form: $g(x) = 3(x - 2) + 3 = 3x - 3$, so $g(0) = -3$. Since $h(x) = g(x) + 7$, the $y$-intercept of $h$ is $h(0) = g(0) + 7 = -3 + 7 = 4$. The value $-3$ comes from finding $g(0)$ but forgetting to add $7$. The value $7$ results from assuming the $y$-intercept of $h$ is simply the constant $7$ that was added, ignoring the $y$-intercept of $g$. The value $10$ comes from evaluating $h(2) = g(2) + 7 = 3 + 7 = 10$ instead of $h(0)$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28SOD64', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A linear function $f$ satisfies $f(3) = 23$ and $f(7) = 51$. What is the rate of change of $f$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{1}{7}$"},{"key":"B","text":"$\\frac{14}{5}$"},{"key":"C","text":"$7$"},{"key":"D","text":"$28$"}]$lyceon_json$::jsonb, 'C', NULL, E'The rate of change is $\\frac{f(7) - f(3)}{7 - 3} = \\frac{51 - 23}{4} = \\frac{28}{4} = 7$. The value $\\frac{1}{7}$ results from inverting the slope, placing the change in $x$ over the change in $f(x)$. The value $\\frac{14}{5}$ comes from adding the $x$-values ($7 + 3 = 10$) instead of subtracting them, giving $\\frac{28}{10} = \\frac{14}{5}$. The value $28$ is the change in function values alone, without dividing by the change in $x$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29VEC06', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of $400$ residents in a city found that $68\\%$ plan to vote in the upcoming election. The margin of error is $\\pm 4\\%$. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $68\\%$ of all residents plan to vote."},{"key":"B","text":"Between $64\\%$ and $72\\%$ of the sampled residents plan to vote."},{"key":"C","text":"It is plausible that between $64\\%$ and $72\\%$ of all residents plan to vote."},{"key":"D","text":"At most $72\\%$ of the sampled residents plan to vote."}]$lyceon_json$::jsonb, 'C', NULL, E'The margin of error creates a confidence interval around the sample statistic to estimate the population parameter. Adding and subtracting $4\\%$ from $68\\%$ gives the interval $64\\%$ to $72\\%$, meaning it is plausible that between $64\\%$ and $72\\%$ of all residents plan to vote. The claim that exactly $68\\%$ of all residents plan to vote ignores the uncertainty captured by the margin of error. Applying the interval to the sample rather than the population confuses the role of the margin of error, which estimates the population value. Stating only an upper bound of $72\\%$ omits the lower bound and misrepresents the interval as one-sided.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BIUFLQ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'A polling organization surveys $1{,}600$ randomly selected voters and finds that $52\\%$ support a ballot measure, with a margin of error of $\\pm 2.5\\%$. A rival organization surveys $400$ randomly selected voters from the same population and finds that $49\\%$ support the measure. Which of the following conclusions is most justified?', NULL, $lyceon_json$[{"key":"A","text":"The rival survey's margin of error is approximately $\\pm 5\\%$, and the two confidence intervals overlap, so the results are not necessarily contradictory."},{"key":"B","text":"The rival survey's margin of error is approximately $\\pm 1.25\\%$, so it is more precise than the first survey."},{"key":"C","text":"Because $52\\%$ and $49\\%$ are on opposite sides of $50\\%$, the surveys reach opposite conclusions about majority support."},{"key":"D","text":"The first survey must be wrong because the rival survey was conducted more recently."}]$lyceon_json$::jsonb, 'A', NULL, E'Margin of error is approximately proportional to $\\frac{1}{\\sqrt{n}}$. Since the rival survey has $\\frac{1}{4}$ the sample size ($400$ vs. $1{,}600$), its margin of error is approximately $\\sqrt{4} = 2$ times larger, giving about $\\pm 5\\%$. The first survey''s interval is $49.5\\%$ to $54.5\\%$, and the rival''s interval is $44\\%$ to $54\\%$; these overlap substantially, so the results are compatible. The claim that the rival margin is $\\pm 1.25\\%$ incorrectly divides the margin of error by the sample size ratio rather than applying the square-root relationship. Arguing that $52\\%$ and $49\\%$ being on opposite sides of $50\\%$ makes the surveys contradictory ignores that both intervals contain $50\\%$ and overlap with each other. Dismissing the first survey as wrong based on timing is unsupported — recency does not determine accuracy.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CN39N2', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'If $4(x + 3) - 7 < 2x + 19$ and $x > -2$, how many integer values of $x$ satisfy both inequalities?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$8$"},{"key":"C","text":"$9$"},{"key":"D","text":"$10$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $8$. Expanding the left side: $4x + 12 - 7 < 2x + 19$, which simplifies to $4x + 5 < 2x + 19$. Subtracting $2x$ and $5$ from both sides gives $2x < 14$, so $x < 7$. Combining with $x > -2$ yields $-2 < x < 7$. The integers in this range are $-1, 0, 1, 2, 3, 4, 5, 6$, which is $8$ values. The distractor $7$ results from a miscalculation that shifts one boundary by $1$, omitting an endpoint integer. The distractor $9$ arises from treating $x > -2$ as $x \\geq -2$, which incorrectly includes $-2$ as a valid integer. The distractor $10$ comes from including both boundary values $-2$ and $7$, treating both strict inequalities as non-strict.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2D52R1J', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'For what value of $k$ does the system of equations below have no solution?$$\\begin{cases} 6x - 9y = 14 \\\\ kx + 12y = -5 \\end{cases}$$', NULL, $lyceon_json$[{"key":"A","text":"$8$"},{"key":"B","text":"$-4$"},{"key":"C","text":"$-18$"},{"key":"D","text":"$-8$"}]$lyceon_json$::jsonb, 'D', NULL, E'The correct answer is $-8$. A system of two linear equations has no solution when the lines are parallel — that is, they have the same slope but different $y$-intercepts. Rewriting the first equation: $-9y = -6x + 14$, so $y = \\frac{2}{3}x - \\frac{14}{9}$, giving a slope of $\\frac{2}{3}$. Rewriting the second equation: $12y = -kx - 5$, so $y = -\\frac{k}{12}x - \\frac{5}{12}$, giving a slope of $-\\frac{k}{12}$. Setting the slopes equal: $-\\frac{k}{12} = \\frac{2}{3}$, so $k = -8$. Since $-\\frac{14}{9} \\neq -\\frac{5}{12}$, the lines are indeed parallel with distinct intercepts, confirming no solution. The distractor $8$ results from dropping the negative sign when solving for $k$. The distractor $-4$ comes from an arithmetic error in simplifying $\\frac{12 \\times 2}{3}$, obtaining $4$ instead of $8$. The distractor $-18$ arises from setting up an incorrect proportion $\\frac{6}{-9} = \\frac{12}{k}$ rather than equating the slopes.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2D5E3NJ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'How many real solutions does the equation $3x^2 + 11x + 9 = 0$ have?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$1$"},{"key":"C","text":"$2$"},{"key":"D","text":"$3$"}]$lyceon_json$::jsonb, 'C', NULL, E'The discriminant is $b^2 - 4ac = 11^2 - 4(3)(9) = 121 - 108 = 13$. Since $13 > 0$, the equation has $2$ real solutions. The answer $0$ results from an arithmetic error such as computing $4(3)(9) = 144$ instead of $108$, which would give a negative discriminant. The answer $1$ comes from confusing a positive discriminant with the condition for exactly one repeated root. The answer $3$ reflects the misconception that a quadratic equation can have three real solutions.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2E25SWN', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'grid_in', E'A rectangular garden has a length of $19$ meters and a width of $7$ meters. What is the area, in square meters, of the garden?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '133', ARRAY['133'], E'The area of a rectangle is length times width: $19 \\times 7 = 133$ square meters.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H7RFZX', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What is the value of $x$ in the equation $7x - 19 = 30$?', NULL, $lyceon_json$[{"key":"A","text":"$-7$"},{"key":"B","text":"$\\frac{11}{7}$"},{"key":"C","text":"$7$"},{"key":"D","text":"$49$"}]$lyceon_json$::jsonb, 'C', NULL, E'Adding $19$ to both sides of $7x - 19 = 30$ gives $7x = 49$. Dividing both sides by $7$ yields $x = 7$. The value $-7$ results from a sign error when dividing $49$ by $7$. The value $\\frac{11}{7}$ comes from subtracting $19$ from $30$ first, getting $11$, then dividing by $7$ — performing operations in the wrong order. The value $49$ is the intermediate result before dividing by $7$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HIKZLX', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A biologist models the population $P$ of a bacterial colony $t$ hours after the start of an experiment with the equation $P = 290 \\cdot (1.13)^t$. Based on this model, which of the following is the best interpretation of $1.13$ in the equation?', NULL, $lyceon_json$[{"key":"A","text":"The population increases by $13$ bacteria each hour."},{"key":"B","text":"The population increases by $13\\%$ each hour."},{"key":"C","text":"The population is $13\\%$ of its initial value after $1$ hour."},{"key":"D","text":"The population reaches $1.13$ times its initial value after the entire experiment."}]$lyceon_json$::jsonb, 'B', NULL, E'In the exponential model $P = 290 \\cdot (1.13)^t$, the base $1.13$ represents the growth factor per unit time. Since $1.13 = 1 + 0.13$, the population increases by $13\\%$ each hour. The choice stating an increase of $13$ bacteria per hour confuses percentage growth with a constant additive rate, which would describe a linear model instead. The choice stating the population is $13\\%$ of its initial value misreads $1.13$ as $0.13$. The choice describing a one-time multiplication by $1.13$ over the entire experiment ignores that the exponent $t$ applies the factor repeatedly each hour.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HP1XF6', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'grid_in', E'A circle in the $xy$-plane has equation $(x - 7)^2 + (y + 3)^2 = 169$. A point on the circle has coordinates $(7, k)$ where $k > 0$. What is the value of $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '10', ARRAY['10'], E'Substituting $x = 7$ into the equation: $(7-7)^2 + (y+3)^2 = 169$, which gives $(y+3)^2 = 169$. Taking the square root: $y + 3 = \\pm 13$. So $y = 10$ or $y = -16$. Since $k > 0$, we have $k = 10$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2J40Q32', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A scatterplot shows the relationship between hours of sunlight per day and the average temperature in degrees Fahrenheit for $12$ cities. The line of best fit has a positive slope. Which of the following is the best interpretation of the positive slope?', NULL, $lyceon_json$[{"key":"A","text":"As hours of sunlight increase, average temperature tends to increase."},{"key":"B","text":"As hours of sunlight increase, average temperature tends to decrease."},{"key":"C","text":"Increased sunlight causes higher temperatures."},{"key":"D","text":"There is no relationship between sunlight and temperature."}]$lyceon_json$::jsonb, 'A', NULL, E'A positive slope in a line of best fit indicates that as the explanatory variable (hours of sunlight) increases, the response variable (average temperature) also tends to increase. The choice stating temperature tends to decrease reverses the direction of the association implied by a positive slope. The choice claiming increased sunlight causes higher temperatures goes beyond correlation to assert causation, which a scatterplot cannot establish. The choice stating no relationship contradicts the existence of a trend line with a nonzero slope.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K2PMXJ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'At how many points do the graphs of $y = 2x^2 - 9x + 4$ and $y = -x^2 + 3x + 10$ intersect in the $xy$-plane?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$1$"},{"key":"C","text":"$2$"},{"key":"D","text":"$3$"}]$lyceon_json$::jsonb, 'C', NULL, E'Setting the equations equal: $2x^2 - 9x + 4 = -x^2 + 3x + 10$, which simplifies to $3x^2 - 12x - 6 = 0$, or $x^2 - 4x - 2 = 0$. The discriminant is $(-4)^2 - 4(1)(-2) = 16 + 8 = 24 > 0$, so there are $2$ intersection points. The answer $0$ results from a sign error when combining terms, such as computing $16 - 8 = 8$ and then further miscalculating to get a negative discriminant. The answer $1$ comes from confusing a positive discriminant with the condition for tangency. The answer $3$ reflects the misconception that two quadratic graphs can intersect at three points.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KCSKD1', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'If $\\frac{5x^3 + 17x^2 - 23x + 6}{x + 4} = ax^2 + bx + c + \\frac{d}{x + 4}$, where $a$, $b$, $c$, and $d$ are constants, what is the value of $c$?', NULL, $lyceon_json$[{"key":"A","text":"$-3$"},{"key":"B","text":"$-11$"},{"key":"C","text":"$11$"},{"key":"D","text":"$50$"}]$lyceon_json$::jsonb, 'B', NULL, E'Performing polynomial long division of $5x^3 + 17x^2 - 23x + 6$ by $x + 4$: dividing $5x^3$ by $x$ gives $5x^2$; multiplying $5x^2(x + 4) = 5x^3 + 20x^2$ and subtracting leaves $-3x^2 - 23x + 6$. Dividing $-3x^2$ by $x$ gives $-3x$; multiplying $-3x(x + 4) = -3x^2 - 12x$ and subtracting leaves $-11x + 6$. Dividing $-11x$ by $x$ gives $-11$; multiplying $-11(x + 4) = -11x - 44$ and subtracting leaves $50$. The quotient is $5x^2 - 3x - 11$ with remainder $50$, so $c = -11$. The value $-3$ is $b$, not $c$, resulting from misreading which coefficient the question asks for. The value $11$ is a sign error on $c$. The value $50$ is the remainder $d$, not $c$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KUSULE', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'grid_in', E'The system of equations $5x + 3y = 41$ and $2x - 3y = -13$ has the solution $(x, y)$. What is the value of $x + 2y$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '18', ARRAY['18'], E'Adding the two equations eliminates $y$: $(5x + 3y) + (2x - 3y) = 41 + (-13)$, which gives $7x = 28$, so $x = 4$. Substituting into $5(4) + 3y = 41$ gives $20 + 3y = 41$, so $3y = 21$ and $y = 7$. Therefore $x + 2y = 4 + 2(7) = 4 + 14 = 18$. A common error is to report just $x + y = 11$ instead of computing $x + 2y$. Another error is a sign mistake when adding the equations, leading to an incorrect value of $x$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LS5UG0', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $3(2x^2 - 7x + 4) - 2(x^2 + 3x - 5)$?', NULL, $lyceon_json$[{"key":"A","text":"$4x^2 - 27x + 22$"},{"key":"B","text":"$4x^2 - 15x + 2$"},{"key":"C","text":"$4x^2 - 27x + 2$"},{"key":"D","text":"$8x^2 - 27x + 22$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distributing gives $6x^2 - 21x + 12 - 2x^2 - 6x + 10$. Combining like terms: $4x^2 - 27x + 22$. The result $4x^2 - 15x + 2$ comes from sign errors when distributing the $-2$, getting $-2(3x) = -6x$ but treating $-2(-5)$ as $-10$ instead of $+10$, so the $x$-terms become $-21x + 6x = -15x$ and constants become $12 - 10 = 2$. The result $4x^2 - 27x + 2$ comes from computing the constant as $12 - 10 = 2$ instead of $12 + 10 = 22$. The result $8x^2 - 27x + 22$ comes from adding the $x^2$ coefficients ($6 + 2 = 8$) instead of subtracting.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M1U8X2', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $g$ is defined by $g(x) = 4x^2 - 7$. What is the value of $g(-3)$?', NULL, $lyceon_json$[{"key":"A","text":"$29$"},{"key":"B","text":"$-43$"},{"key":"C","text":"$43$"},{"key":"D","text":"$-29$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = -3$: $g(-3) = 4(-3)^2 - 7 = 4(9) - 7 = 36 - 7 = 29$. The value $-43$ comes from computing $(-3)^2 = -9$ (a sign error with squaring negatives), giving $4(-9) - 7 = -36 - 7 = -43$. The value $43$ results from adding $36 + 7$ instead of subtracting. The value $-29$ comes from incorrectly treating $4(-3)^2$ as $-(4 \\cdot 9) = -36$, then computing $-36 + 7 = -29$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M5795X', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $\\frac{49p^2 - 4q^2}{7p + 2q}$, where $7p + 2q \\neq 0$?', NULL, $lyceon_json$[{"key":"A","text":"$7p + 2q$"},{"key":"B","text":"$7p - 2q$"},{"key":"C","text":"$49p - 4q$"},{"key":"D","text":"$7p^2 - 2q^2$"}]$lyceon_json$::jsonb, 'B', NULL, E'The numerator $49p^2 - 4q^2$ is a difference of squares: $(7p)^2 - (2q)^2 = (7p + 2q)(7p - 2q)$. Dividing by $(7p + 2q)$ leaves $7p - 2q$. The result $7p + 2q$ comes from canceling incorrectly and keeping the wrong factor. The result $49p - 4q$ comes from dividing each squared coefficient by its base without applying the difference-of-squares factorization. The result $7p^2 - 2q^2$ comes from incorrectly distributing the division across the squared terms.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MMPNSL', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'grid_in', E'A factory produces bolts at a rate of $13$ bolts per $9$ seconds using Machine A, and $17$ bolts per $11$ seconds using Machine B. Both machines run simultaneously. How many complete bolts do the two machines produce together in exactly $99$ seconds?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '296', ARRAY['296'], E'Machine A produces $\\frac{13}{9} \\times 99 = 13 \\times 11 = 143$ bolts in $99$ seconds. Machine B produces $\\frac{17}{11} \\times 99 = 17 \\times 9 = 153$ bolts in $99$ seconds. The total is $143 + 153 = 296$ bolts. A common error is averaging the rates as $\\frac{13 + 17}{9 + 11} \\times 99 = 148.5$, which incorrectly combines the rates into a single fraction. Another error is multiplying each count by $99$ without dividing by the respective time intervals, yielding $13 \\times 99 + 17 \\times 99 = 2970$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MSJZY2', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $f$ is defined by $f(x) = (x - 4)^2 + 7$. The graph of $y = f(x) - 3$ in the $xy$-plane has a vertex at $(h, k)$. What is the value of $k$?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$7$"},{"key":"C","text":"$10$"},{"key":"D","text":"$1$"}]$lyceon_json$::jsonb, 'A', NULL, E'The function $f(x) = (x - 4)^2 + 7$ has vertex $(4, 7)$. The graph of $y = f(x) - 3$ shifts the graph down by $3$, moving the vertex to $(4, 7 - 3) = (4, 4)$. So $k = 4$. The value $7$ results from ignoring the vertical shift and reading the vertex of the original function. The value $10$ comes from adding $3$ instead of subtracting, giving $7 + 3 = 10$. The value $1$ comes from subtracting $3$ from the $x$-coordinate of the vertex instead of the $y$-coordinate, giving $4 - 3 = 1$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NP5CVB', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In triangle $PQR$, the measure of angle $P$ is $47^\\circ$ and the measure of angle $Q$ is $68^\\circ$. What is the measure, in degrees, of angle $R$?', NULL, $lyceon_json$[{"key":"A","text":"$65^\\circ$"},{"key":"B","text":"$55^\\circ$"},{"key":"C","text":"$115^\\circ$"},{"key":"D","text":"$75^\\circ$"}]$lyceon_json$::jsonb, 'A', NULL, E'The sum of angles in a triangle is $180^\\circ$. Angle $R = 180^\\circ - 47^\\circ - 68^\\circ = 65^\\circ$. The answer $55^\\circ$ results from computing $180 - 47 - 68$ incorrectly as $180 - 125 = 55$. The answer $115^\\circ$ comes from adding $47 + 68 = 115$ and reporting that sum rather than subtracting from $180^\\circ$. The answer $75^\\circ$ results from a different arithmetic slip, such as miscomputing $180 - 47 = 143$ and then $143 - 68 = 75$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NTB98M', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'A line is perpendicular to the line $5x - 2y = 13$ and passes through the point $(4, -3)$. What is the $y$-intercept of this line?', NULL, $lyceon_json$[{"key":"A","text":"$-13$"},{"key":"B","text":"$-\\frac{23}{5}$"},{"key":"C","text":"$-\\frac{7}{5}$"},{"key":"D","text":"$\\frac{23}{5}$"}]$lyceon_json$::jsonb, 'C', NULL, E'Rewriting $5x - 2y = 13$ in slope-intercept form gives $y = \\frac{5}{2}x - \\frac{13}{2}$, so the original slope is $\\frac{5}{2}$. The perpendicular slope is $-\\frac{2}{5}$. Using point-slope form: $y - (-3) = -\\frac{2}{5}(x - 4)$, so $y + 3 = -\\frac{2}{5}x + \\frac{8}{5}$. Solving gives $y = -\\frac{2}{5}x + \\frac{8}{5} - \\frac{15}{5} = -\\frac{2}{5}x - \\frac{7}{5}$, and the $y$-intercept is $-\\frac{7}{5}$. The value $-13$ results from using the parallel slope $\\frac{5}{2}$ instead of the perpendicular slope. The value $-\\frac{23}{5}$ comes from using the reciprocal $\\frac{2}{5}$ without negating it. The value $\\frac{23}{5}$ results from a sign error in substituting the point $(4, -3)$, writing $y - 3$ instead of $y + 3$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ONVWSP', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'In a survey of $200$ employees, $110$ drink coffee, $70$ drink tea, and $30$ drink both coffee and tea. If an employee is chosen at random, what is the probability that the employee drinks coffee or tea?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{3}{4}$"},{"key":"B","text":"$\\frac{9}{10}$"},{"key":"C","text":"$\\frac{11}{20}$"},{"key":"D","text":"$\\frac{7}{10}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Using the inclusion-exclusion principle, $P(\\text{coffee or tea}) = \\frac{110 + 70 - 30}{200} = \\frac{150}{200} = \\frac{3}{4}$. The answer $\\frac{9}{10}$ results from adding $110 + 70 = 180$ without subtracting the overlap, giving $\\frac{180}{200}$. The answer $\\frac{11}{20}$ comes from using only the coffee count $\\frac{110}{200}$ and ignoring tea entirely. The answer $\\frac{7}{10}$ comes from using only the tea and overlap counts: $\\frac{70 + 70}{200}$ or a similar miscalculation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OVCU0A', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'The ages of $9$ employees at a company are $23, 27, 29, 31, 34, 36, 38, 41, 47$. A new employee aged $67$ is hired. Which of the following best describes the effect on the median and mean of the ages?', NULL, $lyceon_json$[{"key":"A","text":"Both the median and the mean increase."},{"key":"B","text":"The median increases, but the mean stays the same."},{"key":"C","text":"The mean increases, but the median stays the same."},{"key":"D","text":"Neither the median nor the mean changes."}]$lyceon_json$::jsonb, 'A', NULL, E'The original $9$ values have median $34$ (the $5$th value) and mean $\\frac{306}{9} = 34$. After adding $67$, there are $10$ values. The new median is the average of the $5$th and $6$th values: $\\frac{34 + 36}{2} = 35$, which is greater than $34$. The new mean is $\\frac{306 + 67}{10} = \\frac{373}{10} = 37.3$, which is also greater than $34$. Both measures increase. The choice stating only the median increases ignores how a high outlier pulls the mean upward. The choice stating only the mean increases incorrectly assumes the median of an even-count set stays at the old middle value. The choice stating neither changes fails to account for how adding a value above the mean affects both statistics.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OXM83I', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A machine fills $42$ bottles in $6$ minutes. At this constant rate, how many bottles does the machine fill in $35$ minutes?', NULL, $lyceon_json$[{"key":"A","text":"$210$"},{"key":"B","text":"$252$"},{"key":"C","text":"$245$"},{"key":"D","text":"$1470$"}]$lyceon_json$::jsonb, 'C', NULL, E'The rate is $\\frac{42}{6} = 7$ bottles per minute. In $35$ minutes the machine fills $7 \\times 35 = 245$ bottles. The answer $210$ results from computing $42 \\times 5 = 210$, using $5$ as the multiplier (perhaps from $35 \\div 7$) but applying it to the wrong quantity. The answer $252$ comes from computing $42 \\times 6 = 252$, multiplying by the denominator instead of dividing. The answer $1470$ results from multiplying $42 \\times 35 = 1470$ without accounting for the $6$-minute interval.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OY9IJR', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'A ramp rises at an angle of $19^\\circ$ from the horizontal ground. If the horizontal distance from the base of the ramp to the point directly below the top is $14$ feet, which expression gives the length of the ramp?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{14}{\\cos(19^\\circ)}$"},{"key":"B","text":"$14 \\cos(19^\\circ)$"},{"key":"C","text":"$\\frac{14}{\\sin(19^\\circ)}$"},{"key":"D","text":"$14 \\tan(19^\\circ)$"}]$lyceon_json$::jsonb, 'A', NULL, E'The horizontal distance is the side adjacent to the $19^\\circ$ angle, and the ramp is the hypotenuse. Since $\\cos(19^\\circ) = \\frac{\\text{adjacent}}{\\text{hypotenuse}} = \\frac{14}{\\text{ramp}}$, solving gives ramp $= \\frac{14}{\\cos(19^\\circ)}$. The expression $14\\cos(19^\\circ)$ incorrectly multiplies instead of dividing — this would give the adjacent side if $14$ were the hypotenuse. The expression $\\frac{14}{\\sin(19^\\circ)}$ confuses sine with cosine, using the wrong ratio for the adjacent side. The expression $14\\tan(19^\\circ)$ gives the opposite side (vertical rise), not the hypotenuse.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OZNLKK', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'What is the value of $x$ in the equation $3(2x + 5) - 4(x - 1) = 29$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$9$"},{"key":"C","text":"$10$"},{"key":"D","text":"$\\frac{25}{2}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distributing gives $6x + 15 - 4x + 4 = 29$, which simplifies to $2x + 19 = 29$. Subtracting $19$ yields $2x = 10$, so $x = 5$. The value $9$ results from a sign error when distributing $-4$ across $(x - 1)$, producing $-4x - 4$ instead of $-4x + 4$, which leads to $2x + 11 = 29$ and $x = 9$. The value $10$ comes from stopping at $2x = 10$ without dividing by $2$. The value $\\frac{25}{2}$ arises from failing to distribute the $3$ and $-4$ to all terms inside the parentheses, treating the expression as $6x + 5 - 4x - 1 = 29$ and solving $2x + 4 = 29$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P6HIQU', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which inequality represents all values of $x$ that satisfy $9x - 17 < 64$?', NULL, $lyceon_json$[{"key":"A","text":"$x < 81$"},{"key":"B","text":"$x > 9$"},{"key":"C","text":"$x < 9$"},{"key":"D","text":"$x < \\frac{64}{9}$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $x < 9$. Adding $17$ to both sides of $9x - 17 < 64$ gives $9x < 81$, and dividing both sides by $9$ gives $x < 9$. The distractor $x < 81$ results from adding $17$ but stopping before dividing by $9$, returning an intermediate result. The distractor $x > 9$ results from incorrectly reversing the inequality direction when dividing by a positive number. The distractor $x < \\frac{64}{9}$ comes from dividing $64$ by $9$ without first adding $17$ to both sides.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PIP21K', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A university researcher wants to determine whether a new tutoring program improves exam scores. She allows students to voluntarily sign up for the program. At the end of the semester, she finds that students in the tutoring program scored an average of $11$ points higher on the final exam than students who did not participate. A campus newspaper reports: "Tutoring program boosts exam scores by $11$ points." Which of the following best explains why the newspaper''s claim may be invalid?', NULL, $lyceon_json$[{"key":"A","text":"The sample size of students in the tutoring program was too small to detect an $11$-point difference."},{"key":"B","text":"Students who voluntarily signed up may have been more motivated, making it impossible to attribute the difference solely to the program."},{"key":"C","text":"The researcher should have used a larger margin of error to account for the voluntary enrollment."},{"key":"D","text":"The $11$-point difference is not statistically significant because it is less than one standard deviation."}]$lyceon_json$::jsonb, 'B', NULL, E'Because students self-selected into the tutoring program, this is an observational study, not a randomized experiment. Students who voluntarily enrolled may differ systematically from those who did not — for example, they may be more motivated or academically engaged — creating a confounding variable. This self-selection bias makes it impossible to conclude that the tutoring program alone caused the $11$-point difference. The concern about sample size is not the primary issue; the fundamental flaw is the lack of random assignment, not insufficient power. Suggesting a larger margin of error confuses the concepts of sampling error and study design bias; margin of error does not correct for confounding. Claiming the difference is not significant because it is less than one standard deviation applies an arbitrary threshold without information about the actual standard deviation or hypothesis test.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QH9H57', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'In triangle $DEF$, side $DE = 11$, side $EF = 17$, and side $DF = 23$. Point $G$ lies on $\\overline{DF}$ such that $\\overline{EG}$ bisects angle $DEF$. What is the length of $\\overline{DG}$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{253}{28}$"},{"key":"B","text":"$\\frac{11}{2}$"},{"key":"C","text":"$\\frac{391}{28}$"},{"key":"D","text":"$\\frac{23}{2}$"}]$lyceon_json$::jsonb, 'A', NULL, E'By the angle bisector theorem, $\\frac{DG}{GF} = \\frac{DE}{EF} = \\frac{11}{17}$. Since $DG + GF = 23$, let $DG = 11k$ and $GF = 17k$. Then $28k = 23$, so $k = \\frac{23}{28}$ and $DG = 11 \\cdot \\frac{23}{28} = \\frac{253}{28}$. The answer $\\frac{11}{2}$ comes from incorrectly assuming the bisector divides $DF$ in ratio $1:1$ and taking half of $DE$. The answer $\\frac{391}{28}$ equals $GF = 17 \\cdot \\frac{23}{28}$, the length of the wrong segment. The answer $\\frac{23}{2}$ results from assuming the bisector creates the midpoint of $DF$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QWUSON', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'grid_in', E'In right triangle $ABC$ with the right angle at $C$, $\\sin(A) = \\frac{13}{85}$. What is the value of $\\cos(B)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '13/85', ARRAY['13/85', '0.152', '.152', '0.153', '.153'], E'In a right triangle with the right angle at $C$, angles $A$ and $B$ are complementary, meaning $A + B = 90^\\circ$. A fundamental identity states that $\\cos(B) = \\sin(90^\\circ - B) = \\sin(A)$. Therefore $\\cos(B) = \\frac{13}{85}$. This uses the co-function identity: the sine of one acute angle in a right triangle equals the cosine of the other acute angle, since both reference the same pair of sides but from opposite vertices.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RN5SBR', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A jar contains $5$ red candies, $8$ yellow candies, and $7$ green candies. If one candy is selected at random, what is the probability that it is yellow?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{2}{5}$"},{"key":"B","text":"$\\frac{8}{12}$"},{"key":"C","text":"$\\frac{7}{20}$"},{"key":"D","text":"$\\frac{8}{15}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total number of candies is $5 + 8 + 7 = 20$. The probability of selecting a yellow candy is $\\frac{8}{20} = \\frac{2}{5}$. The answer $\\frac{8}{12}$ results from dividing by only $5 + 7 = 12$, omitting the yellow candies themselves from the total. The answer $\\frac{7}{20}$ comes from counting the green candies instead of the yellow ones. The answer $\\frac{8}{15}$ results from adding $8 + 7 = 15$ as the total, omitting the red candies.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S8Y0GB', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A carpenter charges a flat fee of $\\$47$ plus $\\$29$ per hour for a job. A customer has a budget of no more than $\\$308$. What is the maximum number of complete hours the carpenter can work within this budget?', NULL, $lyceon_json$[{"key":"A","text":"$8$"},{"key":"B","text":"$9$"},{"key":"C","text":"$10$"},{"key":"D","text":"$11$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $9$. The total cost for $h$ hours is $47 + 29h$, and this must satisfy $47 + 29h \\leq 308$. Subtracting $47$ from both sides gives $29h \\leq 261$, and dividing by $29$ gives $h \\leq 9$. Since $29 \\times 9 = 261$ and $47 + 261 = 308$ exactly, the carpenter can work a maximum of $9$ complete hours. The distractor $8$ arises from an arithmetic error when subtracting $47$ from $308$. The distractor $10$ results from ignoring the flat fee and computing $\\lfloor 308 \\div 29 \\rfloor = 10$. The distractor $11$ results from ignoring the flat fee and rounding $308 \\div 29 \\approx 10.62$ upward.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2U9FY6Z', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'If $f(x) = 9x - 23$, what is the value of $f(4)$?', NULL, $lyceon_json$[{"key":"A","text":"$-13$"},{"key":"B","text":"$13$"},{"key":"C","text":"$36$"},{"key":"D","text":"$59$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting $x = 4$ gives $f(4) = 9(4) - 23 = 36 - 23 = 13$. The value $-13$ results from a sign error, computing $23 - 36$ instead of $36 - 23$. The value $36$ comes from computing $9 \\times 4$ but stopping before subtracting $23$. The value $59$ comes from adding $23$ instead of subtracting it: $36 + 23 = 59$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2U9RN59', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'grid_in', E'A data set of $5$ values has a mean of $37$ and a median of $41$. When the smallest value in the set is removed, the mean of the remaining $4$ values is $42$. What is the value that was removed?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '17', ARRAY['17'], E'The sum of all $5$ values is $5 \\times 37 = 185$. After removing the smallest value, the sum of the remaining $4$ values is $4 \\times 42 = 168$. Therefore, the removed value is $185 - 168 = 17$. A common error is computing $37 - 42 = -5$ by subtracting the means directly, which ignores how the mean relates to the total sum. Another error is dividing by $5$ instead of $4$ after removing the value, setting up $\\frac{185 - x}{5} = 42$ and obtaining $x = -25$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UMKMDH', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'Researchers surveyed a random sample of $900$ high school students from a large school district and found that $43\\%$ participate in at least one extracurricular activity. The margin of error for the survey is $\\pm 3\\%$. A second random sample of $225$ students from the same district found that $47\\%$ participate. Which of the following statements is best supported?', NULL, $lyceon_json$[{"key":"A","text":"The second sample proves that participation has increased since the first survey."},{"key":"B","text":"The larger sample is more likely to have a smaller margin of error, so its estimate is more reliable."},{"key":"C","text":"Both samples definitively show that fewer than half of all students participate."},{"key":"D","text":"The two sample results are inconsistent and cannot both be valid."}]$lyceon_json$::jsonb, 'B', NULL, E'Margin of error decreases as sample size increases, so the sample of $900$ students is expected to have a smaller margin of error and thus provides a more reliable estimate than the sample of $225$. The claim that the second sample proves participation has increased conflates sampling variability with a real change; the difference between $43\\%$ and $47\\%$ falls within typical sampling variation. The assertion that both samples definitively show fewer than half participate ignores the margin of error — the true value could plausibly be above $50\\%$ for the second sample. Claiming the results are inconsistent ignores that different random samples from the same population will naturally yield different statistics.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VJRPIY', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A researcher observed that towns with more ice cream shops tend to have higher rates of sunburn. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Ice cream shops cause sunburn."},{"key":"B","text":"There is an association between the number of ice cream shops and sunburn rates."},{"key":"C","text":"Reducing the number of ice cream shops would reduce sunburn rates."},{"key":"D","text":"Sunburn causes people to open ice cream shops."}]$lyceon_json$::jsonb, 'B', NULL, E'Because this is an observational study, only an association (correlation) can be established, not a causal relationship. Both variables are likely influenced by a confounding variable such as warm climate or proximity to beaches. Claiming that ice cream shops cause sunburn incorrectly infers causation from correlation. Asserting that reducing ice cream shops would reduce sunburn assumes a causal mechanism that the study design cannot support. Claiming that sunburn causes people to open ice cream shops reverses the implied direction and also asserts causation without justification.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WMVJVG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'In a school of $500$ students, $64\\%$ participate in at least one extracurricular activity. Of those who participate, $25\\%$ are in the debate club. How many students are in the debate club?', NULL, $lyceon_json$[{"key":"A","text":"$80$"},{"key":"B","text":"$125$"},{"key":"C","text":"$320$"},{"key":"D","text":"$160$"}]$lyceon_json$::jsonb, 'A', NULL, E'First, $64\\%$ of $500 = 0.64 \\times 500 = 320$ students participate in activities. Then $25\\%$ of $320 = 0.25 \\times 320 = 80$ students are in the debate club. The answer $125$ results from incorrectly computing $25\\%$ of $500$ instead of $25\\%$ of $320$, applying the percentage to the wrong base. The answer $320$ is the number who participate in any activity, not specifically the debate club, reflecting incomplete reasoning. The answer $160$ comes from halving $320$ instead of taking one-quarter.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XH57MU', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A chemist mixes two solutions. Solution X contains $7$ grams of salt per $250$ milliliters, and Solution Y contains $11$ grams of salt per $400$ milliliters. If the chemist combines $500$ milliliters of Solution X with $800$ milliliters of Solution Y, what is the total mass of salt, in grams, in the combined mixture?', NULL, $lyceon_json$[{"key":"A","text":"$36$"},{"key":"B","text":"$22$"},{"key":"C","text":"$18$"},{"key":"D","text":"$25$"}]$lyceon_json$::jsonb, 'A', NULL, E'Solution X has $\\frac{7}{250}$ g/mL, so $500$ mL contains $\\frac{7}{250} \\times 500 = 14$ g. Solution Y has $\\frac{11}{400}$ g/mL, so $800$ mL contains $\\frac{11}{400} \\times 800 = 22$ g. The total is $14 + 22 = 36$ g. The answer $22$ results from computing only Solution Y''s contribution without adding Solution X. The answer $18$ comes from simply adding $7 + 11 = 18$ without scaling to the actual volumes combined. The answer $25$ comes from an arithmetic error such as computing $14 + 11$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XUQCP6', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A data set consists of the values $3, 7, 7, 11, 11, 11, 15, 19$. What is the mode of this data set?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$11$"},{"key":"C","text":"$10.5$"},{"key":"D","text":"$19$"}]$lyceon_json$::jsonb, 'B', NULL, E'The mode is the value that appears most frequently. The value $11$ appears $3$ times, which is more than any other value. The value $7$ appears only $2$ times, so selecting it reflects confusion about which value has the highest frequency. The value $10.5$ is the mean of the data set, not the mode, and results from misreading the question as asking for the mean. The value $19$ is the maximum of the data set, not the most frequent value.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"graph_read_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YHGORG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'A jar contains $5$ red, $8$ yellow, and $6$ white gumballs. Two gumballs are drawn at random without replacement. Given that the first gumball drawn is yellow, what is the probability that the second gumball drawn is also yellow?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{8}{19}$"},{"key":"B","text":"$\\frac{7}{18}$"},{"key":"C","text":"$\\frac{7}{19}$"},{"key":"D","text":"$\\frac{8}{18}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The total number of gumballs is $5 + 8 + 6 = 19$. Given the first gumball is yellow, $7$ yellow gumballs remain out of $18$ total gumballs. So the conditional probability is $\\frac{7}{18}$. The answer $\\frac{8}{19}$ uses the original counts without accounting for the removal of one yellow gumball, treating the draws as independent. The answer $\\frac{7}{19}$ correctly reduces the yellow count to $7$ but fails to reduce the total from $19$ to $18$. The answer $\\frac{8}{18}$ reduces the total to $18$ but keeps the yellow count at $8$, neglecting to remove the drawn yellow gumball from the numerator.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZJCWR5', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a diameter of $34$ centimeters. What is the area of the circle, in square centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$289\\pi$"},{"key":"B","text":"$1156\\pi$"},{"key":"C","text":"$34\\pi$"},{"key":"D","text":"$17\\pi$"}]$lyceon_json$::jsonb, 'A', NULL, E'The radius is $\\frac{34}{2} = 17$ cm. The area is $\\pi r^2 = \\pi(17)^2 = 289\\pi$ square centimeters. The answer $1156\\pi$ results from using the diameter instead of the radius: $\\pi(34)^2 = 1156\\pi$. The answer $34\\pi$ comes from computing the circumference formula $\\pi d$ rather than the area formula. The answer $17\\pi$ results from computing only $\\pi r$ instead of $\\pi r^2$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZPOWFN', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $x$-coordinate of the $x$-intercept of the line $3x + 7y = 21$?', NULL, $lyceon_json$[{"key":"A","text":"$-7$"},{"key":"B","text":"$3$"},{"key":"C","text":"$7$"},{"key":"D","text":"$21$"}]$lyceon_json$::jsonb, 'C', NULL, E'The $x$-intercept occurs where $y = 0$. Substituting gives $3x + 7(0) = 21$, so $3x = 21$ and $x = 7$. The value $-7$ results from a sign error when dividing. The value $3$ comes from finding the $y$-intercept ($x = 0$ gives $7y = 21$, $y = 3$) instead of the $x$-intercept. The value $21$ comes from reading the constant term directly without dividing by the coefficient of $x$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21MB93H', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'The traditional view holds that the Ancestral Puebloans abandoned their cliff dwellings in the late thirteenth century solely because of prolonged drought. Recent tree-ring analyses from Mesa Verde, however, show that rainfall levels during the abandonment period were comparable to those of earlier decades when the settlements thrived. _______ some archaeologists now argue that social and political disruptions, rather than climate alone, drove the exodus.', $lyceon_json$[{"key":"A","text":"Nevertheless,"},{"key":"B","text":"Accordingly,"},{"key":"C","text":"For instance,"},{"key":"D","text":"Meanwhile,"}]$lyceon_json$::jsonb, 'B', NULL, E'The tree-ring data undermine the drought-only explanation, and the third sentence draws a logical conclusion from that evidence: archaeologists now point to social and political factors. "Accordingly," correctly signals that the conclusion follows from the preceding evidence. "Nevertheless," implies a concession or contrast, but the third sentence builds on the second rather than contradicting it. "For instance," signals an example, yet the third sentence states a broader argument rather than illustrating a specific point. "Meanwhile," signals simultaneous events, which mischaracterizes the logical relationship between the evidence and the conclusion archaeologists draw from it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21VPVHP', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'The ceramicist Yuna Takahashi is known for vessels that appear almost impossibly thin, their translucent walls revealing shadows of the potter''s fingers. Critics have praised the ______ of her technique, noting that each piece requires dozens of incremental refinements before the clay reaches its final, paper-like delicacy.', $lyceon_json$[{"key":"A","text":"clamor"},{"key":"B","text":"meticulousness"},{"key":"C","text":"turbulence"},{"key":"D","text":"camouflage"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is "meticulousness." The passage emphasizes dozens of incremental refinements and paper-like delicacy, indicating extreme care and precision in technique. "Clamor" refers to a loud, confused noise or outcry, which is incoherent when describing a ceramicist''s technique. "Turbulence" denotes violent, disordered motion, the opposite of the controlled refinement described. "Camouflage" means concealment by disguise, which has no logical connection to the craft of making thin pottery.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW227ZWCC', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Researchers at the University of Groningen have found that certain species of Arctic terns can sleep while gliding over open ocean, a behavior previously observed only in frigatebirds. _______ the discovery challenges the long-held assumption that sustained wakefulness is necessary for migratory flight in smaller seabirds.', $lyceon_json$[{"key":"A","text":"In other words,"},{"key":"B","text":"As a result,"},{"key":"C","text":"By contrast,"},{"key":"D","text":"Specifically,"}]$lyceon_json$::jsonb, 'B', NULL, E'The second sentence presents a consequence of the discovery described in the first sentence: because Arctic terns can sleep while gliding, the assumption about sustained wakefulness is now challenged. The transition "As a result," correctly signals this cause-and-effect relationship. "In other words," incorrectly signals a restatement, but the second sentence adds a new implication rather than rephrasing the first. "By contrast," incorrectly signals opposition, yet the second sentence follows logically from the first rather than contradicting it. "Specifically," incorrectly signals elaboration on a detail, but the second sentence describes an outcome, not a narrower restatement of the discovery.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW247Q6II', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing a persuasive essay and wants to acknowledge a limitation of mycelium-based packaging while arguing that its environmental benefits still justify broader adoption. Which choice most effectively accomplishes this goal?', E'- Mycelium-based packaging is grown from fungal root networks bound to agricultural waste such as hemp husks or corn stalks.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25HS690', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The Italian National Institute of Geophysics and Volcanology monitors seismic activity across the Mediterranean basin. This year, a series of unexpected seismic events beneath the floor of the Adriatic Sea _____ prompted Italian geologists to reconsider the tectonic stability of the northeastern coastline, where several major port cities sit atop sedimentary formations once considered geologically inert.', $lyceon_json$[{"key":"A","text":"have"},{"key":"B","text":"has"},{"key":"C","text":"having"},{"key":"D","text":"had"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct choice is ''has'' because the subject of the sentence is ''a series,'' which is singular and requires the singular auxiliary verb ''has.'' The plural noun ''events'' in the prepositional phrase ''of unexpected seismic events'' does not determine the verb''s number; it merely modifies ''series.'' The choice ''have'' incorrectly treats the plural ''events'' as the subject. The choice ''having'' transforms the clause into a participial phrase, creating a sentence fragment rather than a complete sentence. The choice ''had'' incorrectly uses the past perfect tense, but the time marker ''this year'' indicates the current year and calls for the present perfect ''has prompted.''', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25U8QKM', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text?', E'The island fox, found exclusively on six of California''s Channel Islands, nearly went extinct in the late 1990s due to predation by golden eagles. Conservation agencies launched a multifaceted recovery program that included captive breeding, eagle relocation, and habitat restoration. <u>By 2016, the island fox population had rebounded to over 1,500 individuals on Santa Cruz Island alone.</u> The species was subsequently removed from the endangered species list.', $lyceon_json$[{"key":"A","text":"To provide a specific result that illustrates the success of the recovery program"},{"key":"B","text":"To introduce a new threat facing the island fox population"},{"key":"C","text":"To explain why golden eagles were relocated from the islands"},{"key":"D","text":"To challenge the claim that the island fox was ever endangered"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating that the sentence provides a specific result illustrating the recovery program''s success. The underlined sentence gives a concrete population figure (over 1,500 individuals by 2016) directly following the description of conservation efforts, serving as evidence that those efforts worked. The choice about introducing a new threat misidentifies the rhetorical purpose: the population rebound is a positive outcome, not a threat. The choice about explaining eagle relocation confuses two different parts of the passage; the underlined sentence reports a population outcome, not reasons for relocation. The choice about challenging the endangered status contradicts the passage''s logic, since the population recovery confirmed rather than questioned the prior endangerment.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25WFZ2W', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding from Ikeda''s study, if true, would most effectively undermine the conclusion presented in the text?', E'Neuroscientist Yuki Ikeda conducted a study in which participants listened to unfamiliar musical compositions while undergoing functional MRI scans. Ikeda observed that participants who reported higher emotional responses to the music showed significantly greater activation in the nucleus accumbens, a brain region associated with reward processing. Ikeda concluded that the emotional impact of music is primarily mediated by the brain''s dopaminergic reward circuitry, suggesting that musical pleasure operates through the same neural mechanisms as other reward-driven experiences such as eating or receiving monetary gains.', $lyceon_json$[{"key":"A","text":"Participants who were administered a dopamine antagonist before the listening sessions reported emotional responses of similar intensity and showed comparable nucleus accumbens activation."},{"key":"B","text":"The degree of nucleus accumbens activation correlated with participants' prior musical training."},{"key":"C","text":"Participants who reported low emotional responses still showed activation in auditory cortex regions."},{"key":"D","text":"Some participants exhibited strong emotional responses to compositions from cultural traditions unfamiliar to them."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer would most effectively undermine Ikeda''s conclusion by showing that blocking dopamine did not reduce emotional responses or nucleus accumbens activation, which would challenge the claim that dopaminergic reward circuitry primarily mediates musical emotion. If the effect persists without dopamine, the proposed mechanism cannot be the primary driver. The finding about musical training correlating with activation introduces a confound but does not directly challenge the dopamine-mediated mechanism itself. Activation in auditory cortex among low-response participants concerns a different brain region and does not address the specific role of dopaminergic reward circuitry. Cross-cultural emotional responses are interesting but actually consistent with Ikeda''s conclusion that a universal reward mechanism underlies musical pleasure.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW270VF81', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In 2019, geochemist Priya Subramaniam analyzed isotopic ratios in feldspar crystals recovered from a volcanic deposit in central Java, seeking evidence that two historically documented eruptions had originated from the same magma chamber. The isotopic signatures of the crystals from the earlier eruption, however, bore no resemblance to those from the later _____ the two events, despite occurring just forty-three years apart and less than eleven kilometers from each other, had drawn from entirely separate reservoirs of molten rock.', $lyceon_json$[{"key":"A","text":"eruption; nonetheless,"},{"key":"B","text":"eruption, that is,"},{"key":"C","text":"eruption; similarly,"},{"key":"D","text":"eruption; that is,"}]$lyceon_json$::jsonb, 'D', NULL, E'The correct choice uses a semicolon followed by ''that is'' to join two independent clauses where the second clause restates and clarifies the geological meaning of the first. The isotopic signatures bearing ''no resemblance'' means, in precise geological terms, that the eruptions drew from separate magma reservoirs, and ''that is'' signals exactly this kind of clarification. The choice using ''nonetheless'' is logically wrong because ''nonetheless'' signals concession or contrast, but the second clause explains the first rather than contradicting it. The choice using ''similarly'' is logically wrong because the second clause does not present a parallel case; it elaborates on what the lack of resemblance means. The choice placing only a comma before ''that is'' creates a comma splice: when ''that is'' joins two independent clauses, a semicolon is required before the conjunctive expression, not merely a comma.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27E9HO9', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'A team of marine biologists studying the seafloor near the Galápagos Rift in 1977 discovered thriving communities of giant tube worms, clams, and other organisms clustered around hydrothermal vents. These vents release superheated, mineral-rich water from beneath the ocean crust. Prior to this discovery, scientists had assumed that all complex ecosystems depended on sunlight as their primary energy source. The vent communities, however, rely on chemosynthetic bacteria that convert hydrogen sulfide into usable energy, sustaining an entire food web in total darkness.', $lyceon_json$[{"key":"A","text":"The discovery of hydrothermal vent communities revealed that complex ecosystems can be sustained by chemical energy rather than sunlight."},{"key":"B","text":"Giant tube worms are uniquely adapted to survive in the extreme temperatures found near hydrothermal vents."},{"key":"C","text":"Marine biologists in the 1970s were primarily focused on mapping the geological features of the ocean floor."},{"key":"D","text":"Chemosynthetic bacteria are more efficient at producing energy than photosynthetic organisms."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer states that the discovery of vent communities showed complex ecosystems can run on chemical energy instead of sunlight. This captures the passage''s central point: scientists previously assumed sunlight was necessary, but chemosynthetic bacteria at the vents proved otherwise. The choice about tube worm adaptations to extreme temperatures focuses on one organism''s traits, which the passage does not discuss in detail. The choice about mapping geological features misrepresents the biologists'' purpose, which was studying the seafloor ecosystem. The claim that chemosynthetic bacteria are more efficient than photosynthetic organisms introduces a comparison the passage never makes.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW296N9SV', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In a laboratory at the University of São Paulo, biochemist Renata Figueiredo studies the antimicrobial properties of compounds found in Brazilian tree frogs. After isolating a previously unknown peptide from the skin secretions of the milk _____ observed that the substance inhibited the growth of several antibiotic-resistant bacteria in controlled trials, a discovery that could eventually lead to new treatments for drug-resistant infections.', $lyceon_json$[{"key":"A","text":"frog, Figueiredo"},{"key":"B","text":"frog; Figueiredo"},{"key":"C","text":"frog. Figueiredo"},{"key":"D","text":"frog Figueiredo"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct choice places a comma after ''frog'' to separate the introductory participial phrase ''After isolating a previously unknown peptide from the skin secretions of the milk frog'' from the main clause. A semicolon after ''frog'' is incorrect because the introductory phrase is a dependent element, not an independent clause, and a semicolon can only join two independent clauses. A period after ''frog'' would turn the introductory phrase into a sentence fragment. Omitting the comma entirely leaves the introductory phrase improperly joined to the main clause, violating the convention that a long introductory phrase must be followed by a comma.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29E0FFA', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'Economist Priya Narasimhan argues that many developing nations have adopted austerity measures not because empirical evidence supports their effectiveness but because international lending institutions have ______ such policies as prerequisites for financial assistance. Narasimhan contends that this dynamic leaves borrowing governments with little genuine latitude to pursue alternative fiscal strategies.', $lyceon_json$[{"key":"A","text":"stipulated"},{"key":"B","text":"forecasted"},{"key":"C","text":"absolved"},{"key":"D","text":"commemorated"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is "stipulated." The passage states that lending institutions have imposed austerity measures as prerequisites for aid, and to stipulate means to demand or specify as a required condition, which precisely fits this context. "Forecasted" means to predict future events, but the passage describes a requirement being imposed, not a prediction being made. "Absolved" means to free from blame or guilt, which is the opposite of imposing a requirement. "Commemorated" means to honor or remember a past event, which is entirely unrelated to the act of setting conditions for financial assistance.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AFW62S', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from a literary scholar, if accurate, would most directly weaken the claim made in the text?', E'Literary historian Marcus Ó Briain has argued that the Irish-language poetry of the seventeenth century was primarily a vehicle for political resistance against English colonial rule. According to Ó Briain, the aisling—a vision poem in which Ireland appears as a woman in distress—functioned almost exclusively as coded political commentary, with poets using the genre to rally support for the Stuart cause and express defiance of Cromwellian authority.', $lyceon_json$[{"key":"A","text":"\"Numerous aisling poems from this period address themes of unrequited love, seasonal change, and spiritual longing without any identifiable political referent or allegorical framework.\""},{"key":"B","text":"\"The aisling tradition drew on earlier medieval conventions that predated English colonial involvement in Ireland by several centuries.\""},{"key":"C","text":"\"Many seventeenth-century Irish poets composed works in both Irish and English, demonstrating bilingual literary fluency.\""},{"key":"D","text":"\"Political allegory was a common literary device across multiple European traditions during the seventeenth century.\""}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer directly challenges Ó Briain''s claim that the aisling functioned ''almost exclusively'' as political commentary by presenting evidence that many such poems had no political content at all. This would undermine the exclusivity of his characterization. The quotation about medieval precedents addresses the genre''s origins but does not counter the claim about its seventeenth-century political function. The observation about bilingual poets concerns linguistic range, not the political content of aisling poems specifically. The point about allegory being common across Europe actually contextualizes the practice rather than weakening the specific claim about Irish poetry''s political function.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AGQ9CX', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes the relationship between the two texts?', E'Text 1: Architectural historian Dara Mbeki argues that the concrete Brutalist structures built across sub-Saharan African capital cities in the 1960s and 1970s represented a genuine expression of postcolonial national identity. She contends that newly independent governments chose Brutalism deliberately, viewing its raw materiality and monumental scale as symbols of self-determination that rejected the ornamental colonial styles imposed by European powers.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AQSIWA', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Based on the texts, how would the author of Text 1 most likely characterize the approach described in Text 2?', E'Text 1: Cognitive scientist Mirela Petrescu has criticized the trend of using brain-imaging data to draw conclusions about subjective emotional experience. She argues that neural activation patterns, while physiologically real, are too coarse-grained to distinguish between qualitatively different emotions: the amygdala, for instance, responds to surprise, fear, and even positive excitement. Mapping a brain region''s activity onto a single emotional label, Petrescu maintains, reflects the researcher''s interpretive framework more than the participant''s inner life.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2C9OF48', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing a research summary and wants to emphasize a surprising contrast between two findings about octopus cognition. Which choice most effectively accomplishes this goal?', E'- Octopuses have roughly 500 million neurons, about two-thirds of which are located in their arms rather than in a centralized brain.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CFTJ45', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The rings visible in a cross section of a tree trunk record not only the tree''s age but also the environmental conditions it experienced each year. A narrow ring indicates a year of drought or extreme _____ a wider ring suggests a year of abundant rainfall and favorable growing conditions.', $lyceon_json$[{"key":"A","text":"cold; conversely,"},{"key":"B","text":"cold; similarly,"},{"key":"C","text":"cold; consequently,"},{"key":"D","text":"cold, conversely,"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct choice uses a semicolon followed by ''conversely'' to join two independent clauses that present contrasting observations: a narrow ring signals drought or cold, while a wider ring signals abundant rainfall and favorable conditions. ''Conversely'' accurately captures this contrastive relationship between opposing environmental interpretations. The choice using ''similarly'' is logically wrong because the two clauses describe opposite conditions—scarcity versus abundance—not parallel ones. The choice using ''consequently'' is logically wrong because a wider ring is not a consequence of a narrow ring; each ring represents a different year with independent conditions. The choice placing a comma before ''conversely'' creates a comma splice: ''conversely'' is a conjunctive adverb, not a coordinating conjunction, and cannot join two independent clauses with only a comma.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2F59CWS', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The interdisciplinary research initiative—which brings together climatologists, marine biologists, and oceanographers from eleven countries—_____ that warming ocean currents along the western Antarctic Peninsula have accelerated the fragmentation of ice shelves at nearly twice the rate that models from the early 2000s had predicted.', $lyceon_json$[{"key":"A","text":"has demonstrated"},{"key":"B","text":"have demonstrated"},{"key":"C","text":"are demonstrating"},{"key":"D","text":"demonstrate"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct choice is ''has demonstrated'' because the subject of the sentence is ''initiative,'' which is singular and takes the singular verb form ''has.'' The long parenthetical clause set off by em dashes—''which brings together climatologists, marine biologists, and oceanographers from eleven countries''—contains several plural nouns but does not change the grammatical number of the subject. The choice ''have demonstrated'' incorrectly uses a plural verb, likely due to attraction to nearby plural nouns such as ''climatologists,'' ''biologists,'' ''oceanographers,'' or ''countries.'' The choice ''are demonstrating'' is similarly incorrect because it uses a plural verb form, and the progressive aspect is unnecessary in this context. The choice ''demonstrate'' lacks the third-person singular inflection ''-s'' required when the subject is the singular noun ''initiative.''', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FVDX3X', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing an article for a campus newsletter and wants to introduce the topic of vertical farming to readers who may be unfamiliar with it. Which choice most effectively accomplishes this goal?', E'- Vertical farming grows crops in stacked indoor layers rather than on traditional outdoor fields.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2I06IZ9', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1: Ornithologist Ewan Callister maintains that the common raven''s problem-solving abilities are primarily instinctive. He points to the consistency of ravens'' tool-use behaviors across geographically isolated populations as evidence that these skills are genetically encoded rather than learned.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ITC42K', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Archaeologist Dmitri Volkov spent three years excavating a Bronze Age settlement near Novosibirsk, expecting to find evidence of a nomadic hunter-gatherer culture. The excavation instead revealed permanent stone foundations, elaborate drainage channels, and large communal grain _____ the settlement''s inhabitants had developed a far more complex and sedentary way of life than Volkov had anticipated.', $lyceon_json$[{"key":"A","text":"stores; evidently,"},{"key":"B","text":"stores; nevertheless,"},{"key":"C","text":"stores, consequently,"},{"key":"D","text":"stores; for example,"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct choice uses a semicolon followed by ''evidently'' to join two independent clauses with a conjunctive adverb signaling that the second clause is a conclusion drawn from the evidence in the first. The physical evidence—permanent foundations, drainage channels, and grain stores—makes it evident that the inhabitants lived a complex, sedentary lifestyle. The choice using ''nevertheless'' is logically wrong because ''nevertheless'' signals concession or contrast, but the second clause follows logically from the evidence rather than contradicting it. The choice with a comma before ''consequently'' creates a comma splice: two independent clauses cannot be joined by only a comma and a conjunctive adverb. The choice using ''for example'' is logically wrong because the second clause draws a general conclusion from the evidence rather than providing a specific example of it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2M5YZJL', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Linguist Yaron Matras has argued that Romani, the language of the Roma people, preserves syntactic structures from medieval Indo-Aryan languages that have since disappeared from Hindi and Punjabi. Some scholars question whether these structures are genuine retentions or later developments influenced by contact with Balkan languages. _______ the very features Matras identifies as archaic Indo-Aryan retentions — such as postposed definite articles and case-marking clitics — are also characteristic of Romanian, Greek, and Albanian, the dominant languages of the regions where Romani has been spoken for centuries.', $lyceon_json$[{"key":"A","text":"In support of Matras's position,"},{"key":"B","text":"In fact,"},{"key":"C","text":"Regardless,"},{"key":"D","text":"To illustrate Matras's claim,"}]$lyceon_json$::jsonb, 'B', NULL, E'The second sentence introduces skeptics who question Matras''s interpretation, and the third sentence elaborates on their reasoning by noting that the features in question also appear in Balkan contact languages. "In fact," correctly signals that the following evidence substantiates the skeptics'' concern by demonstrating concrete overlap with Balkan languages. "In support of Matras''s position," reverses the rhetorical direction: the evidence that the features overlap with Balkan languages strengthens the critics'' contact-based alternative, not Matras''s retention hypothesis. "Regardless," signals dismissal of the preceding debate, but the third sentence engages directly with it rather than setting it aside. "To illustrate Matras''s claim," misidentifies the function of the evidence: the overlap with Balkan languages undermines rather than exemplifies the archaic-retention interpretation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2N62OKG', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Ethologist Daniela Rössler documented that certain wasp species appear to enter a dream-like state during sleep, exhibiting rapid antennal movements analogous to the rapid eye movements observed in mammals. Critics objected that the antennal twitches might simply reflect involuntary neural discharges rather than genuine sleep-stage cycling. _______ Rössler''s subsequent experiments showed that wasps deprived of these twitching episodes displayed the same compensatory rebound behavior seen in REM-deprived rats, suggesting the movements serve a regulatory function rather than arising from random firing.', $lyceon_json$[{"key":"A","text":"In addition,"},{"key":"B","text":"To address this objection,"},{"key":"C","text":"Similarly,"},{"key":"D","text":"In other words,"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage presents a claim by Rössler, then a counterargument from critics, then Rössler''s experimental response to that counterargument. The transition "To address this objection," correctly identifies the third sentence as a direct response to the critics'' challenge. "In addition," merely signals additive information and fails to capture the responsive relationship between Rössler''s follow-up experiments and the specific criticism they were designed to counter. "Similarly," signals a parallel, but the third sentence answers the objection rather than describing a comparable phenomenon. "In other words," signals a restatement, yet the third sentence introduces new experimental evidence rather than rephrasing the critics'' point or the original finding.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OANFND', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'The fruit fly Drosophila melanogaster has been a staple of genetics research for over a century, in part because its genome has been thoroughly mapped and its roughly twelve-day generation cycle permits rapid observation of inherited traits. Researchers studying a newly discovered insect species with a similar genome size but a generation cycle of approximately ninety days would most likely find that, compared to working with Drosophila, ________', $lyceon_json$[{"key":"A","text":"experiments tracking trait inheritance across multiple generations would require substantially more time."},{"key":"B","text":"the new species' genome would be more difficult to sequence accurately."},{"key":"C","text":"the new species would display fewer observable inherited traits."},{"key":"D","text":"the new species would be unsuitable for any form of genetic research."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer logically follows from the passage''s emphasis on Drosophila''s twelve-day generation cycle as an advantage for observing inherited traits rapidly. A species with a ninety-day cycle would require roughly seven and a half times longer per generation, making multi-generational experiments substantially more time-consuming. The claim about sequencing difficulty has no basis in the passage, which states the genome sizes are similar. The suggestion of fewer observable traits conflates generation speed with the number of heritable characteristics, which are unrelated. Calling the species entirely unsuitable for genetic research is an extreme overstatement—longer generation time is a practical disadvantage, not a disqualification.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2P87CKY', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice most accurately describes the main finding presented in the text?', E'Ecologist Renata Vilhena''s 2023 analysis of pollinator visitation patterns across fragmented Atlantic Forest remnants in southeastern Brazil yielded a counterintuitive result. While smaller forest fragments (under eleven hectares) predictably attracted fewer pollinator species than larger tracts, the per-flower visitation rate in these smaller fragments was actually forty-seven percent higher than in contiguous forest. Vilhena attributed this to reduced interspecific competition: with fewer pollinator species present, the remaining generalist species—particularly the stingless bee Tetragonisca angustula—monopolized floral resources more intensively, compensating for diminished species richness through behavioral plasticity.', $lyceon_json$[{"key":"A","text":"Smaller forest fragments had fewer pollinator species but higher per-flower visitation rates, likely because reduced competition allowed generalist species to forage more intensively."},{"key":"B","text":"Pollinator species diversity in smaller forest fragments was unexpectedly higher than in larger tracts due to reduced interspecific competition."},{"key":"C","text":"The stingless bee Tetragonisca angustula was the only pollinator species capable of surviving in fragmented Atlantic Forest habitats."},{"key":"D","text":"Fragmented forests are more ecologically productive than contiguous forests because generalist pollinators are inherently more efficient than specialist species."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer precisely captures Vilhena''s finding: smaller fragments had fewer species but higher per-flower visitation, attributed to reduced competition enabling generalist species to forage more intensively. The choice claiming species diversity was higher in smaller fragments reverses the passage''s stated finding—smaller fragments had fewer pollinator species, not more. The claim that Tetragonisca angustula was the only surviving pollinator overstates the passage, which says it monopolized resources among the remaining generalist species, not that it was the sole survivor. The assertion that fragmented forests are more ecologically productive overall extrapolates far beyond the passage''s narrow finding about per-flower visitation rates.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UNH6PD', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In the summer of 2023, a team of paleontologists from the University of Alberta traveled to the badlands of Dinosaur Provincial Park in southeastern Alberta. _____ the nearly complete skeleton of a juvenile hadrosaurid was painstakingly removed from the cliff face over the course of eleven weeks, requiring the construction of a temporary scaffolding system anchored directly into the surrounding sandstone.', $lyceon_json$[{"key":"A","text":"Encased for an estimated seventy million years in a stratum of Late Cretaceous mudstone,"},{"key":"B","text":"Encasing for an estimated seventy million years in a stratum of Late Cretaceous mudstone,"},{"key":"C","text":"Having encased for an estimated seventy million years in a stratum of Late Cretaceous mudstone,"},{"key":"D","text":"To be encased for an estimated seventy million years in a stratum of Late Cretaceous mudstone,"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct choice is the past participle ''Encased,'' which functions as a passive participial modifier correctly indicating that the skeleton had been encased within the rock. The subject of the main clause, ''the nearly complete skeleton,'' is the entity that was encased, so the modifier is properly attached. The choice beginning with ''Encasing'' employs the present participle in the active voice, which would illogically imply that the skeleton was performing the act of encasing something else rather than being encased itself. The choice beginning with ''Having encased'' similarly uses the active voice in the perfect form, incorrectly suggesting the skeleton had encased something before being removed. The choice beginning with ''To be encased'' uses an infinitive of purpose, illogically implying that the skeleton was removed from the cliff in order to be encased, reversing the actual sequence of events.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2V6GQJ3', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the overall purpose of the text?', E'When the playwright Lorraine Hansberry wrote A Raisin in the Sun in 1959, critics celebrated it as a breakthrough in representing African American family life on Broadway. Subsequent scholarship, however, has tended to flatten the play into a straightforward narrative of racial uplift, overlooking its more unsettling interrogation of class aspiration. Walter Lee Younger''s obsessive pursuit of a liquor-store investment, for instance, is not simply a bid for respectability; it exposes the corrosive influence of capitalist striving on familial bonds—a theme Hansberry explored with deliberate ambivalence rather than the moral clarity later commentators have imposed on her work.', $lyceon_json$[{"key":"A","text":"To argue that later scholars have oversimplified the thematic complexity of Hansberry's most famous play"},{"key":"B","text":"To demonstrate that A Raisin in the Sun was poorly received by critics when it first appeared"},{"key":"C","text":"To compare Hansberry's treatment of class aspiration with that of other mid-century playwrights"},{"key":"D","text":"To chronicle the stages of Hansberry's career from her earliest writings to her final works"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating that the text argues later scholars have oversimplified the play''s thematic complexity. The passage explicitly contrasts the initial critical reception with subsequent scholarship that "flattened" the play, then demonstrates a more nuanced reading of class aspiration through Walter Lee''s storyline. The choice about poor initial reception directly contradicts the passage, which states critics "celebrated" the play as a breakthrough. The choice about comparing Hansberry to other playwrights introduces a comparison the passage never makes—no other playwright is mentioned. The choice about chronicling career stages misrepresents the passage''s scope, which focuses entirely on one play and its critical interpretation rather than surveying Hansberry''s career.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VMVO7E', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'According to the text, which choice best describes the relationship between the two phenomena Okafor''s study examined?', E'Sociologist Adaeze Okafor investigated whether increased participation in neighborhood governance meetings correlates with residents'' perceptions of local safety. Analyzing survey data from 1,743 households across seventeen mid-sized cities, Okafor found that neighborhoods where at least thirty-one percent of households sent a representative to monthly governance meetings reported notably higher perceived safety scores than neighborhoods with lower participation rates. Crucially, Okafor noted that actual crime statistics did not differ significantly between high- and low-participation neighborhoods, suggesting that the sense of security stemmed from the communal engagement itself rather than from measurable reductions in criminal activity.', $lyceon_json$[{"key":"A","text":"Higher participation in governance meetings was associated with greater perceived safety, even though actual crime rates were similar across neighborhoods."},{"key":"B","text":"Neighborhoods with higher governance participation experienced both lower crime rates and higher perceived safety."},{"key":"C","text":"Residents who attended governance meetings were more likely to report crimes, leading to more accurate safety perceptions."},{"key":"D","text":"Governance meeting participation had no meaningful effect on how residents perceived their neighborhood's safety."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer accurately captures the passage''s stated finding: higher meeting participation correlated with greater perceived safety, but crime statistics did not actually differ between the groups. The choice claiming both lower crime rates and higher perceived safety contradicts the passage, which explicitly states crime statistics did not differ significantly. The choice about residents reporting crimes more frequently introduces a causal mechanism the passage never mentions. The choice stating participation had no meaningful effect directly contradicts Okafor''s central finding of notably higher perceived safety scores in high-participation neighborhoods.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2W5WW92', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'After earning his doctorate at Charles University in Prague, geochemist Tomáš Novák devoted his career to mapping the mineral wealth of Central Europe''s ancient mountain ranges. By the time Novák published his landmark findings on rare-earth mineral deposits in the Ore Mountains of Bohemia, he _____ more than nine hundred core samples from seventeen different sites across the region.', $lyceon_json$[{"key":"A","text":"has analyzed"},{"key":"B","text":"had analyzed"},{"key":"C","text":"analyzed"},{"key":"D","text":"was analyzing"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct choice is ''had analyzed'' because the past perfect tense is required to indicate that the analysis of core samples was completed before the past action of publishing. The construction ''by the time [past event], [subject] had [past participle]'' is standard for establishing that one past action preceded another. The choice ''has analyzed'' uses the present perfect, which is inconsistent with the past-tense narrative established by ''published'' and ''devoted.'' The choice ''analyzed'' uses the simple past, which fails to convey that the analysis was completed prior to the publication. The choice ''was analyzing'' uses the past progressive, implying that the analysis was still ongoing at the time of publication rather than already complete.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WFXA3W', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'Marine biologists studying the deep-sea anglerfish have documented its remarkable ability to ______ prey in total darkness. Using a bioluminescent lure that dangles from a modified dorsal spine, the fish draws smaller organisms close enough to capture with a single rapid strike.', $lyceon_json$[{"key":"A","text":"attract"},{"key":"B","text":"demolish"},{"key":"C","text":"catalog"},{"key":"D","text":"irrigate"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is "attract." The passage describes how the anglerfish uses a bioluminescent lure to draw prey close, which is the definition of attracting. "Demolish" means to destroy completely, which does not fit the context of luring prey nearer. "Catalog" means to systematically list or record items, which is incoherent in the context of a predatory strategy. "Irrigate" means to supply water to land or crops, which has no logical connection to a fish''s hunting behavior.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2X7LSQI', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Economists studying the adoption of mobile banking in rural Senegal between 2018 and 2022 observed that villages where at least one resident had previously migrated to an urban center adopted mobile banking at nearly triple the rate of villages with no migration history. The researchers controlled for income levels, proximity to cellular towers, and literacy rates, finding that none of these variables accounted for the disparity. The researchers therefore suggested that the primary driver of adoption was ________', $lyceon_json$[{"key":"A","text":"the transfer of technological familiarity and trust from returning migrants to their home communities through informal social networks."},{"key":"B","text":"the higher average income levels that returning migrants brought back to their villages."},{"key":"C","text":"the superior cellular network infrastructure that was preferentially built in villages with migration connections."},{"key":"D","text":"a government subsidy program that specifically targeted villages with diaspora connections for mobile banking enrollment."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the strongest inference because the passage has already controlled for income, infrastructure (cellular tower proximity), and literacy, eliminating those as explanations. What remains is the social influence of migrants who experienced urban technology firsthand and could transmit familiarity and trust to their communities. The claim about higher income directly contradicts the passage, which states income levels were controlled for and did not account for the disparity. The suggestion about superior infrastructure is likewise ruled out—proximity to cellular towers was controlled for. The government subsidy explanation introduces an external program with no basis in the passage and would represent an institutional, not social, mechanism that the researchers apparently found no evidence of.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2X7MLUV', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Art conservator Elise Daubigny analyzed pigment samples from a fifteenth-century altarpiece attributed to a workshop in Bruges. She found that while the blue pigments in the sky and drapery were natural ultramarine—derived from lapis lazuli imported at great expense from Central Asia—the blue used in minor decorative borders was azurite, a less costly mineral available locally. This distribution pattern suggests that the workshop ________', $lyceon_json$[{"key":"A","text":"strategically allocated its most expensive materials to the most visually prominent areas of the composition."},{"key":"B","text":"was unable to obtain sufficient quantities of lapis lazuli to complete the entire altarpiece."},{"key":"C","text":"preferred azurite to ultramarine for all applications but was required by patrons to use the more expensive pigment."},{"key":"D","text":"used identical techniques for applying both ultramarine and azurite pigments."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the most logical inference: the workshop used expensive ultramarine in visually prominent areas (sky, drapery) and cheaper azurite in minor borders, indicating a deliberate cost-allocation strategy tied to visual importance. The claim about insufficient supply goes beyond the evidence—the pattern appears deliberate rather than forced by scarcity, since the expensive pigment was used where it mattered most. The assertion about the workshop preferring azurite contradicts the passage''s implication that ultramarine was chosen intentionally for prominent areas, not reluctantly under patron pressure. The suggestion about identical application techniques addresses a topic the passage does not discuss at all.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XEM4LV', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'Historians have long attributed the decline of the Khmer Empire primarily to the Thai invasions of the fourteenth century. Recent archaeological work at Angkor, however, has revealed evidence of severe hydraulic infrastructure failures—collapsed reservoirs, silted canals—that preceded the military incursions by several decades. These findings suggest that environmental degradation weakened the empire''s agricultural base, leaving it vulnerable to external pressures that might otherwise have been repelled.', $lyceon_json$[{"key":"A","text":"It presents a traditional explanation, introduces contradicting evidence, and proposes a revised interpretation"},{"key":"B","text":"It describes an archaeological method, evaluates its reliability, and recommends improvements"},{"key":"C","text":"It compares two empires, identifies a similarity between them, and draws a general conclusion"},{"key":"D","text":"It poses a question about military strategy, examines two possible answers, and selects the more plausible one"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice describing a progression from traditional explanation to contradicting evidence to revised interpretation. The passage first states the long-held view (Thai invasions caused decline), then introduces archaeological findings that challenge it (infrastructure failures preceded the invasions), and finally proposes a new understanding (environmental degradation weakened the empire first). The choice about evaluating an archaeological method mischaracterizes the passage, which uses archaeological evidence to revise a historical narrative rather than assessing a method. The choice about comparing two empires is factually wrong—only the Khmer Empire is discussed. The choice about military strategy misrepresents the passage''s focus, which is on the causes of decline rather than on evaluating competing military strategies.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YQBYUS', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researcher''s hypothesis?', E'Geochemist Hana Petrovská hypothesized that the unusually high concentration of iridium found in certain clay layers in central Slovakia was deposited by volcanic eruptions rather than by meteorite impacts. She reasoned that if the iridium originated from regional volcanic activity, then the clay layers should also contain elevated levels of other volcanically associated elements, such as selenium and arsenic, in proportions consistent with known volcanic signatures from the same geological period.', $lyceon_json$[{"key":"A","text":"The clay layers contain selenium and arsenic at ratios matching those found in volcanic deposits from the same era."},{"key":"B","text":"Iridium concentrations in the clay layers are higher than those typically associated with volcanic eruptions."},{"key":"C","text":"Similar clay layers in other parts of Europe also contain elevated iridium levels."},{"key":"D","text":"Meteorite impact craters from the same period have been identified in nearby regions."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer directly supports Petrovská''s hypothesis by confirming her specific prediction: if the iridium is volcanic, the clay should contain selenium and arsenic at volcanic ratios from that period. Finding those elements at the predicted ratios would validate her reasoning. The claim that iridium concentrations exceed typical volcanic levels would actually weaken, not support, her volcanic origin hypothesis. The finding that similar layers exist elsewhere is geographically interesting but does not distinguish between volcanic and meteorite origins. The discovery of nearby impact craters would support the competing meteorite hypothesis rather than Petrovská''s volcanic explanation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
